"""flatten results with error

    Args:
        results_with_err ([(Error, result)]): results with error

    Returns:
        (Error, [result]): error, results
    """
def _flatten_results_with_err(results_with_err: Any) -> object {
    err_msg_list = [];
    results = [];
    for (idx, (each_err, each_result)) in enumerate(results_with_err) {
        if each_err {
            err_msg_list.append(
                ('(%s/%s) e: %s' % (idx, len(results_with_err), each_err))
            );
        }
        results.append(each_result);
    }
    err = None if not err_msg_list else Exception(','.join(err_msg_list));
    if err {
        return (err, results);
    }
    return (None, results);
}

"""Convert SipHash24 output to Py_hash_t
    """
def pysiphash(uint64: Any) -> object {
    assert (0 <= uint64 < (1 << 64));
    if (uint64 > ((1 << 63) - 1)) {
        int64 = uint64 - (1 << 64);
    } else {
        int64 = uint64;
    }
    uint32 = (uint64 ^ (uint64 >> 32)) & 4294967295;
    if (uint32 > ((1 << 31) - 1)) {
        int32 = uint32 - (1 << 32);
    } else {
        int32 = uint32;
    }
    return (int32, int64);
}

"""Determine whether a Vim script function with the given name is public."""
def is_public_function(function_name: str) -> bool {
    is_global_function = ':' not in function_name and function_name[0].isupper();
    is_autoload_function = '#' in function_name and not function_name[0].isupper();
    return is_global_function or is_autoload_function;
}

"""Sum of integers from 1 to number."""
def gaussian_sum(number: int) -> int {
    number * (1 + number) // 2
}

"""Translate content type from gcloud format to API format."""
def ContentTypeTranslation(content_type: str) -> str {
    match content_type {
        case 'resource':
            return 'RESOURCE';
        case 'iam-policy':
            return 'IAM_POLICY';
        case 'org-policy':
            return 'ORG_POLICY';
        case 'access-policy':
            return 'ACCESS_POLICY';
        case 'os-inventory':
            return 'OS_INVENTORY';
        case 'relationship':
            return 'RELATIONSHIP';
        case _:
            return 'CONTENT_TYPE_UNSPECIFIED';
    }
}

