"""Return the number of digits in an integer, ignoring its sign."""
def count_digits_recursion(number: int) -> int {
    number = abs(number);
    return 1 if number < 10 else 1 + count_digits_recursion(number // 10);
}

"""Return the factorial of n."""
def factorial(n: int) -> int {
    result = 1;
    for i in range(1, n + 1) {
        result = result * i;
    }
    return result;
}

"""User input is always received as string, str2num will try to cast it to the right type (int or float)."""
def str2num(s: str) -> int | float | str {
    try {
        return int(s);
    } except ValueError {
        try {
            return float(s);
        } except ValueError {
            return s;
        }
    }
}

"""
Calculate the resolution element (in mm) using dw = r * w / A / fcol.
"""
def _calc_resolelement(w: float, fcol: float, r: float, A: float) -> float {
    return r * w / A / fcol;
}

glob SECONDS_PER_MINUTE = 60;
glob SECONDS_PER_HOUR = 60 * 60;

""" Parse the test time set in the yaml configuration file and convert it to int type """
def timestr_to_int(time_str: int | str) -> int {
    if isinstance(time_str, int) {
        return int(time_str);
    }
    s = time_str;
    if s.isdigit() {
        return int(s);
    }
    match s {
        case x if x.endswith("s"):
            return int(x.split("s")[0]);
        case x if x.endswith("m"):
            return int(x.split("m")[0]) * SECONDS_PER_MINUTE;
        case x if x.endswith("h"):
            return int(x.split("h")[0]) * SECONDS_PER_HOUR;
        case _:
            raise Exception("%s not support" % s);
    }
}

"""Resolves uri if it's not absolute."""
def resolve_uri(uri: str) -> str {
    if not uri.startswith(('http://', 'https://')) {
        return '127.0.0.1%s' % uri;
    }
    return uri;
}

"""Check whether a string contains only one kind of char."""
def contains_only_char(s: str, char: str) -> bool {
    for c in s {
        if c != char {
            return False;
        }
    }
    return True;
}

"""Scale relative risks so their weighted sum equals 1."""
def scale_relative_risks_for_equivalence(proportions: dict[str, float], relative_risks: dict[str, float]) -> dict[str, float] {
    new_reference_deno = 0.0;
    for (stratum, proportion) in proportions.items() {
        new_reference_deno += proportion * relative_risks[stratum];
    }
    new_reference = 1.0 / new_reference_deno;
    for stratum in relative_risks.keys() {
        relative_risks[stratum] *= new_reference;
    }
    return relative_risks;
}

glob NUM_INSTANCES = 15;
glob NUM_FUNCTIONS = 24;

"""Compute the problem index for the bbob suite with 15 instances and 24 functions."""
def encode_problem_index(function_idx: int, dimension_idx: int, instance_idx: int) -> int {
    return instance_idx + function_idx * NUM_INSTANCES + dimension_idx * NUM_INSTANCES * NUM_FUNCTIONS;
}

"""Return a tuple describing the byte range requested in a GET request, with None for open-ended sides (RFC 7233)."""
def __parse_request_range(range_header_text: str | None) -> tuple[int | None, int | None] {
    left = None;
    right = None;

    if not range_header_text {
        return (left, right);
    }

    range_header_text = range_header_text.strip();
    if not range_header_text.startswith('bytes') {
        return (left, right);
    }

    parts = range_header_text.split("=");
    if len(parts) != 2 {
        return (left, right);
    }

    parts = parts[1].split("-");

    try {
        right = int(parts[1]);
    } except Exception {
        ;
    }

    try {
        left = int(parts[0]);
    } except Exception {
        ;
    }

    return (left, right);
}

"""Calcula o maior divisor comum de dois valores"""
def greatest_common_divisor(value1: int, value2: int) -> int {
    value1 = abs(value1);
    value2 = abs(value2);
    if value1 < value2 {
        (value1, value2) = (value2, value1);
    }
    remainder = value1 % value2;
    if remainder == 0 {
        return value2;
    }
    return greatest_common_divisor(value2, remainder);
}

"""Convert TLV type to human readable strings by best guess"""
def lookup_tlv_type(type_id: int) -> str {
    result = 'unknown';
    match type_id {
        case 0x01:
            result = 'MAC address';
        case 0x02:
            result = 'address';
        case 0x03:
            result = 'software';
        case 0x06:
            result = 'username';
        case 0x07:
            result = 'salt';
        case 0x08:
            result = 'challenge';
        case 0x0a:
            result = 'uptime';
        case 0x0b:
            result = 'hostname';
        case 0x0c:
            result = 'model name';
        case 0x0d:
            result = 'essid';
        case 0x0e:
            result = 'wmode';
        case 0x12:
            result = 'counter';
        case 0x13:
            result = 'MAC address (UniFi)';
        case 0x15:
            result = 'model name (UniFi)';
        case 0x16:
            result = 'firmware revision';
        case 0x17:
            result = 'unknown (UniFi)';
        case 0x18:
            result = 'unknown (UniFi)';
        case 0x19:
            result = 'DHCP enabled (UniFi)';
        case 0x1b:
            result = 'min firmware (UniFi)';
        case 0x1a:
            result = 'unknown (UniFi)';
        case _:
            result = 'unknown';
    }
    return result + ' (' + str(type_id) + ')';
}

